export const FORMS_PART1 = [
form("1040","U.S. Individual Income Tax Return","1040 series","Main individual return","The principal federal income tax return used by U.S. citizens and resident aliens to report income, deductions, credits, tax, withholding, estimated payments and refund or balance due. It is the central summary document into which schedules and supporting forms feed.","Most U.S. individual taxpayers whose gross income, filing status, age, dependency status or special circumstances create a filing requirement. A taxpayer may also file voluntarily to claim a refund or refundable credit.","W-2 and 1099 income, Schedules 1–3, Schedules A–E and other schedules feed relevant lines of Form 1040. The return computes taxable income, tax, credits, payments and refund/balance due.","The return is generally filed annually for a calendar-year individual. Filing an extension extends the time to file, not the time to pay tax. A return must be signed/authorized and supported by accurate records.","2026 standard deductions: $16,100 Single/MFS; $24,150 HOH; $32,200 MFJ/QSS. A dependent's standard deduction is generally limited to the greater of $1,350 or earned income plus $450. Confirm age/blindness additions and all final instructions.","A single taxpayer with $70,000 wages, $1,000 interest and $5,000 eligible adjustments has AGI of $66,000. If the taxpayer uses the $16,100 standard deduction, taxable income before other adjustments is $49,900.","Think of Form 1040 as the summary, not the source document for every item. Identify the schedule or information return that supports each reported amount.","individual return;1040;AGI;taxable income;refund;balance due","https://www.irs.gov/forms-pubs/about-form-1040",["Core return","Individuals"]),
form("1040-SR","U.S. Tax Return for Seniors","1040 series","Senior-friendly layout","An optional alternative layout of Form 1040 designed with larger type and a standard-deduction chart for eligible older taxpayers. It generally uses the same tax rules and calculations as Form 1040.","Taxpayers age 65 or older may use it; it is optional, not a separate tax regime.","Same income, schedules, credits and tax computations flow to the corresponding Form 1040-SR lines.","Age-based eligibility is tied to the taxpayer's age by the end of the tax year. The form does not itself create a special tax rate or extra credit.","The 2026 standard deduction and age/blindness additional deduction rules apply as they do to Form 1040; use the current 1040-SR instructions for the chart.","A taxpayer who is 67 may choose Form 1040-SR for readability while reporting the same pension and interest amounts as on Form 1040.","Do not mistake the SR label for a different tax calculation.","senior;age 65;1040-SR","https://www.irs.gov/forms-pubs/about-form-1040-sr",["Optional layout","Individuals"]),
form("1040-NR","U.S. Nonresident Alien Income Tax Return","1040 series","Nonresident alien return","Reports U.S.-source income and effectively connected income of a nonresident alien, with deductions and treaty positions as permitted by law.","Nonresident aliens engaged in a U.S. trade or business or with other U.S. income requiring a return; special rules apply to students, teachers, dependents and treaty claims.","U.S. source wage, business, investment and other income is reported on the applicable 1040-NR lines and schedules, including Schedule OI and Schedule NEC where applicable.","Residency classification under the green-card and substantial-presence tests comes before choosing 1040 vs 1040-NR. Treaty provisions may modify domestic-law treatment but require proper disclosure and analysis.","There is no single universal gross-income filing threshold: filing depends on income type, withholding, treaty position and statutory filing rules.","A nonresident alien with effectively connected U.S. consulting income may report net business income on Form 1040-NR and calculate tax under applicable rules.","Determine residency status first; nonresident alien is not synonymous with foreign citizen.","nonresident alien;NRA;1040-NR;US source income","https://www.irs.gov/forms-pubs/about-form-1040-nr",["International","Individuals"]),
form("1040-X","Amended U.S. Individual Income Tax Return","1040 series","Amend a filed return","Corrects an already-filed individual income tax return, generally explaining changes to income, deductions, credits, filing status or tax.","Individual taxpayers who need to correct a previously filed Form 1040, 1040-SR or 1040-NR as allowed by the instructions.","Amended figures reconcile original amounts, net changes and corrected amounts. Supporting schedules and forms are attached as necessary.","A taxpayer generally cannot use Form 1040-X to replace an unprocessed original return. Some changes can be made through electronic filing where supported; procedures depend on year and return type.","Refund claims generally face a 3-years-from-filing or 2-years-from-payment limitation, whichever is later, subject to statutory exceptions and special rules.","A taxpayer omitted $2,000 of deductible IRA contribution information. The taxpayer evaluates eligibility, recalculates AGI/tax and reports the change on Form 1040-X.","Amending a return is different from filing an extension; explain each change and attach supporting documents.","amended return;correction;refund claim;1040-X","https://www.irs.gov/forms-pubs/about-form-1040-x",["Amendment","Individuals"]),
form("1040-ES","Estimated Tax for Individuals","1040 series","Quarterly estimated payments","Provides worksheets and payment vouchers for individuals who pay income tax not fully covered by withholding, including self-employed taxpayers and investors.","Individuals expecting to owe at least $1,000 after withholding and refundable credits may need estimated payments, unless a safe harbor or exception applies.","Estimated payments are credited as payments on Form 1040. Taxpayer generally tracks each installment and payment date.","Common safe harbors: pay at least 90% of current-year tax or 100% of prior-year tax; prior-year percentage generally rises to 110% for certain higher-income taxpayers. Annualized income installment method can help uneven income.","2026 estimated tax due dates are generally Apr. 15, Jun. 15, Sep. 15, 2026 and Jan. 15, 2027, adjusted for weekends/holidays and special circumstances.","A sole proprietor expects $12,000 of federal tax after withholding. The taxpayer calculates required annual installments and pays using IRS Direct Pay or EFTPS where appropriate.","A safe harbor avoids an underpayment penalty; it does not necessarily mean the taxpayer has paid the full balance due.","estimated tax;quarterly;safe harbor;1040-ES","https://www.irs.gov/forms-pubs/about-form-1040-es",["Payments","Individuals"]),
form("Schedule 1","Additional Income and Adjustments to Income","1040 schedules","Additional income / adjustments","Reports specified additional income not entered directly on the main Form 1040 and adjustments to income that reduce gross income to adjusted gross income.","Individuals with income or adjustments listed in the schedule instructions, such as business income, unemployment compensation, educator expenses or deductible SE tax.","Part I additional income generally flows to Form 1040 additional income; Part II adjustments flow to Form 1040 adjustments and determine AGI.","The schedule has distinct parts: additional income and adjustments. Do not net an adjustment against a gross-income item without following the form's structure.","No universal dollar threshold; each line has its own eligibility and limitation rules.","Schedule C net profit of $20,000 is included as additional income; the deductible portion of self-employment tax is reported as an adjustment, subject to calculation.","Know the difference between an income item and an above-the-line adjustment.","Schedule 1;additional income;adjustments;AGI","https://www.irs.gov/forms-pubs/about-schedule-1-form-1040",["Flow-through","Individuals"]),
form("Schedule 2","Additional Taxes","1040 schedules","Additional tax liabilities","Reports taxes that are not included in the ordinary income tax calculation on Form 1040, including certain alternative minimum tax and other additional taxes.","Individuals with additional taxes described in the schedule instructions, such as AMT, excess advance premium tax credit repayment or certain retirement-related taxes.","Schedule 2 tax amounts flow to the additional-tax section of Form 1040.","A tax can be reported on Schedule 2 even if it is not a penalty. Review the specific line and related form.","Thresholds depend on the underlying tax: AMT exemption/phase-out, net investment income tax, additional Medicare tax and other provisions have separate tests.","A taxpayer with specified incentive stock option adjustments may need Form 6251 to calculate AMT, with the resulting amount flowing through Schedule 2.","Schedule 2 is a collection point for additional taxes, not a single tax calculation.","Schedule 2;AMT;additional Medicare tax;NIIT","https://www.irs.gov/forms-pubs/about-schedule-2-form-1040",["Flow-through","Individuals"]),
form("Schedule 3","Additional Credits and Payments","1040 schedules","Other credits / payments","Reports certain nonrefundable credits, refundable credits and other payments not entered directly on the main Form 1040.","Individuals claiming credits or payments listed in the schedule instructions, such as foreign tax credit or certain general business credits passed through to an individual.","Part I nonrefundable credits and Part II other payments/refundable credits flow to their corresponding Form 1040 sections.","Separate nonrefundable credits from refundable payments; the distinction determines whether a credit can exceed regular income tax liability.","Each credit has its own limits, eligibility and carryover rules. There is no single Schedule 3 threshold.","A taxpayer with qualifying foreign taxes may complete Form 1116 and report the allowed foreign tax credit on Schedule 3.","Trace the underlying credit form before entering the Schedule 3 amount.","Schedule 3;foreign tax credit;other credits;payments","https://www.irs.gov/forms-pubs/about-schedule-3-form-1040",["Flow-through","Individuals"]),
form("Schedule A","Itemized Deductions","1040 schedules","Itemize eligible deductions","Lists allowable itemized deductions, including qualifying medical expenses, state/local taxes, mortgage interest, charitable gifts and certain casualty/theft losses.","Taxpayers whose allowable itemized deductions exceed the standard deduction or who are required to itemize under special rules.","Allowed Schedule A total flows to the deductions section of Form 1040.","Medical expenses are generally deductible only to the extent they exceed 7.5% of AGI. SALT and other limits must be checked under the law applicable to the tax year.","2026 standard deduction comparison: $16,100 Single/MFS; $24,150 HOH; $32,200 MFJ/QSS. SALT cap and any income-based limitation should be verified under 2026 law.","A taxpayer with $9,000 deductible medical expenses, $8,000 state/local taxes and $12,000 mortgage interest compares the allowable Schedule A total with the standard deduction.","Do not assume every personal expense is deductible; itemized deductions are statutory categories with limits.","itemized;medical;SALT;mortgage interest;charity","https://www.irs.gov/forms-pubs/about-schedule-a-form-1040",["Deductions","Individuals"]),
form("Schedule B","Interest and Ordinary Dividends","1040 schedules","Interest / dividends detail","Lists taxable interest and ordinary dividends when reporting requirements are met and identifies certain foreign account or trust interests.","Individuals with reportable interest/dividends above applicable filing thresholds or with specified foreign account/trust situations.","Taxable interest and ordinary dividends generally flow to their respective Form 1040 lines; qualified dividends are also used for preferential-rate tax computation.","Certain foreign account and trust questions must be answered even when dollar amounts are small. Filing Schedule B can be required by the nature of the account, not merely income total.","Common filing trigger: taxable interest or ordinary dividends over $1,500, plus separate foreign account/trust triggers. Verify current instructions.","A taxpayer receives $900 bank interest and $800 ordinary dividends: the combined amounts exceed $1,500, generally requiring Schedule B.","Interest and dividends are different income categories; qualified dividends are a subset of ordinary dividends.","interest;dividends;foreign account;Schedule B","https://www.irs.gov/forms-pubs/about-schedule-b-form-1040",["Income","Individuals"]),
form("Schedule C","Profit or Loss From Business","1040 schedules","Sole proprietor business","Computes profit or loss from a sole proprietorship or qualifying single-member LLC treated as disregarded for federal income tax purposes.","Sole proprietors and eligible single-member LLC owners carrying on a trade or business.","Net profit generally flows to Schedule 1 and Form 1040; it is also generally used in the Schedule SE calculation.","Deduct ordinary and necessary business expenses. Personal expenses are not deductible business costs. Inventory, home office, vehicle, depreciation and startup-cost rules can require separate analysis.","Generally, net self-employment earnings of $400 or more trigger a Schedule SE filing requirement, subject to exceptions.","A freelance designer has $82,000 gross receipts and $32,000 deductible expenses. Schedule C net profit is $50,000 before other adjustments.","A 1099 does not determine taxability; reconcile gross receipts to books and all information returns.","sole proprietor;business income;1099-NEC;1099-K;Schedule C","https://www.irs.gov/forms-pubs/about-schedule-c-form-1040",["Business","Individuals"]),
form("Schedule D","Capital Gains and Losses","1040 schedules","Capital asset sales","Summarizes capital gains and losses, generally using Form 8949 for detailed transactions where required.","Taxpayers with reportable sales or exchanges of capital assets, capital gain distributions or carryovers.","Net capital gain/loss generally flows to Form 1040; preferential-rate tax may be calculated using Schedule D Tax Worksheet or Qualified Dividends and Capital Gain Tax Worksheet.","Net short-term and long-term results are separately calculated and then combined under ordering rules. Capital loss deduction for individuals is generally limited to $3,000 ($1,500 MFS) against ordinary income, with carryforward.","The $3,000 annual net capital loss deduction limit is generally applicable; special rules apply to married filing separately and capital loss carryovers.","A taxpayer has $4,000 long-term gain and $7,500 short-term loss, creating a $3,500 net capital loss; generally $3,000 is deductible this year and $500 carries forward.","Holding period and character matter. A capital gain distribution is not the same as wages or interest.","capital gain;capital loss;8949;long term;short term","https://www.irs.gov/forms-pubs/about-schedule-d-form-1040",["Investments","Individuals"]),
form("Schedule E","Supplemental Income and Loss","1040 schedules","Rentals / pass-throughs","Reports income or loss from rental real estate, royalties, partnerships, S corporations, estates and trusts, and residual interests.","Individuals receiving income or loss from activities listed in Schedule E instructions.","Schedule E net income/loss generally flows to Schedule 1 and Form 1040; passive activity limitations may require Form 8582.","Rental real estate can be passive even when profitable; active participation special allowance, real-estate professional rules and at-risk/basis limitations may apply.","The special rental real estate loss allowance may be up to $25,000, phased out as modified AGI rises from $100,000 to $150,000; MFS restrictions apply. Verify all eligibility rules.","A taxpayer receives a Schedule K-1 from an S corporation and reports applicable ordinary business income on Schedule E, subject to basis, at-risk and passive-loss rules.","A K-1 is not automatically taxable in full; character, basis and loss limitations matter.","rental;royalty;Schedule K-1;partnership;S corporation","https://www.irs.gov/forms-pubs/about-schedule-e-form-1040",["Pass-through","Individuals"]),
form("Schedule F","Profit or Loss From Farming","1040 schedules","Farm business income","Computes profit or loss from farming operations, including farm receipts and deductible farm expenses.","Individuals operating a farm as a trade or business, including sole proprietor farmers.","Net farm profit generally flows to Schedule 1/Form 1040 and is generally included in self-employment tax computation.","Farm accounting method, inventory, livestock, crop insurance, cooperatives and conservation payments can affect timing and character.","No single filing threshold; net earnings and gross income filing rules apply. Farm optional method and special estimated-tax rules may be available.","A farmer reports crop sales, government payments and deductible seed, fertilizer and equipment costs to determine Schedule F profit.","Distinguish a farm business from a hobby; profit motive and facts govern business treatment.","farmer;farm income;crop;livestock;Schedule F","https://www.irs.gov/forms-pubs/about-schedule-f-form-1040",["Business","Individuals"]),
form("Schedule H","Household Employment Taxes","1040 schedules","Nanny / household worker taxes","Computes Social Security, Medicare, federal unemployment and withheld federal income tax obligations for household employees.","Household employers who pay household employees wages meeting applicable employment-tax thresholds or have withholding obligations.","Household employment taxes are generally reported with the employer's Form 1040, unless the employer elects or is required to use other permitted reporting.","A household worker is not an independent contractor merely because the work occurs in a private home. The household employer's control over how work is performed is important.","Social Security/Medicare household employee wage threshold is $3,000 for 2026; FUTA has a separate $1,000 cash-wage test in any calendar quarter in current or prior year. Verify 2026 instructions.","A family pays a nanny $18,000 in cash wages during 2026; Schedule H is generally used to calculate applicable household employment taxes.","The worker classification test comes before deciding whether Schedule H applies.","household employee;nanny;FICA;FUTA;Schedule H","https://www.irs.gov/forms-pubs/about-schedule-h-form-1040",["Payroll","Individuals"]),
form("Schedule J","Income Averaging for Farmers and Fishermen","1040 schedules","Farm / fishing income averaging","Allows eligible farmers and fishermen to elect to average certain current-year farming or fishing income over the prior three years for income tax rate computation.","Individuals with qualifying farming or fishing income who elect the provision.","Schedule J computes the tax benefit and feeds the tax calculation on Form 1040; it does not change the amount of income reported.","Income averaging is an election for tax computation, not a deferral or exclusion of income. Eligibility and election calculations are technical.","No fixed income threshold; requires qualifying net farm/fishing income and prior-year tax data.","A farmer has unusually high current-year income after several lower-income years and calculates whether Schedule J lowers tax by spreading elected income across prior years.","Do not confuse income averaging with cash-basis accounting or installment sale treatment.","farmers;fishermen;income averaging;Schedule J","https://www.irs.gov/forms-pubs/about-schedule-j-form-1040",["Special computation","Individuals"]),
form("Schedule R","Credit for the Elderly or the Disabled","1040 schedules","Elderly / disabled credit","Determines eligibility and computes the credit for certain elderly or permanently and totally disabled individuals with low income.","Taxpayers age 65 or older, or under 65 and retired on permanent and total disability, who meet income and nontaxable Social Security/pension limits.","Credit generally flows through Schedule 3 to Form 1040 and is nonrefundable.","Eligibility depends on filing status, age/disability, income ceiling and amount of nontaxable benefits. Many taxpayers do not qualify because income is too high.","Base amounts and income limits are statutory and comparatively low; use the current Schedule R instructions rather than assuming all seniors qualify.","A 68-year-old taxpayer with limited income checks Schedule R's income and nontaxable benefit limits before claiming the credit.","Age 65 alone does not guarantee the credit.","elderly;disabled;credit;Schedule R","https://www.irs.gov/forms-pubs/about-schedule-r-form-1040",["Credit","Individuals"]),
form("Schedule SE","Self-Employment Tax","1040 schedules","Social Security / Medicare tax","Calculates Social Security and Medicare taxes on net earnings from self-employment and the deductible portion of that tax.","Sole proprietors, partners and certain other individuals with net earnings from self-employment generally of $400 or more.","Tax flows to Schedule 2 and Form 1040; deductible half of SE tax generally flows to Schedule 1 as an adjustment to income.","Net earnings are generally 92.35% of business profit. Combined SE tax rate is generally 15.3% (12.4% Social Security plus 2.9% Medicare), subject to wage base and Additional Medicare Tax rules.","2026 Social Security wage base and any additional tax thresholds must be confirmed from the current SSA/IRS annual figures. Do not assume the entire profit is subject to both components if wages already use the wage base.","$50,000 net profit × 92.35% = $46,175 net earnings. At 15.3%, illustrative SE tax is about $7,065 before wage-base coordination and other adjustments.","SE tax is not the same as income tax. The deduction for one-half of SE tax is an adjustment, not a business expense.","self employment;SE tax;Schedule SE;92.35%;FICA","https://www.irs.gov/forms-pubs/about-schedule-se-form-1040",["Payroll","Individuals"]),
form("Schedule 8812","Credits for Qualifying Children and Other Dependents","1040 schedules","CTC / ODC computation","Computes the child tax credit, additional child tax credit and credit for other dependents, as applicable.","Taxpayers claiming qualifying children or other dependents who meet statutory identification, age, relationship, residency and support rules.","Nonrefundable child/dependent credit flows to Form 1040; refundable ACTC is reported through the applicable refundable-credit section.","A qualifying child for CTC generally must be under age 17 at year-end and meet relationship, residency, support, dependency and valid SSN requirements. Credit phase-out applies.","2026 credit amount and phase-out thresholds must be checked against the final 2026 Schedule 8812 and current law; do not rely on pre-2025 figures.","A taxpayer claims one eligible child and one qualifying relative: the child may qualify for CTC while the relative may qualify for the other-dependent credit if all tests are met.","CTC child age test is under 17; qualifying child for dependency can have a higher age limit.","CTC;ACTC;other dependent;Schedule 8812","https://www.irs.gov/forms-pubs/about-schedule-8812-form-1040",["Credits","Individuals"]),
form("W-2","Wage and Tax Statement","W-series","Employee annual wage statement","Reports wages, tips, other compensation and withheld taxes, plus information such as Social Security wages, Medicare wages, retirement plan indicator and benefits.","Employer furnishes to employee and files copies with Social Security Administration; employee uses it to prepare the individual return.","Box 1 wages generally flow to Form 1040 wages. Federal withholding in Box 2 is a payment credit. Boxes 3–6 report Social Security/Medicare wage and tax data.","Box 1, Box 3 and Box 5 can differ because of pre-tax benefits and wage-base rules. Tips, dependent care benefits and retirement plan indicators may require additional analysis.","Employers generally furnish W-2 by Jan. 31 (next business day when applicable). 2026 wage bases and withholding amounts are not the same as Box 1 wages.","W-2 Box 1 = $62,000 and Box 2 = $6,200. The employee reports $62,000 wages and claims $6,200 federal withholding, subject to reconciliation.","Do not use Social Security wages (Box 3) as the Form 1040 wage amount.","wages;withholding;employee;Box 1;Box 2","https://www.irs.gov/forms-pubs/about-form-w-2",["Information return","Employment"]),
form("W-2G","Certain Gambling Winnings","W-series","Reportable gambling winnings","Reports certain gambling winnings and any federal income tax withheld from those winnings.","Payer furnishes to winner and files with IRS when reporting requirements are met.","Winnings generally reported as other income or on the applicable gambling income line; withholding is claimed as a payment. Gambling losses may be deductible only under strict rules and generally require itemizing.","Winnings are generally taxable even when no Form W-2G is issued. Losses do not offset winnings for gross-income reporting; deduction rules and recordkeeping apply.","Reporting thresholds vary by game and are subject to statutory changes; consult current W-2G instructions for each wager type.","A taxpayer receives $2,000 reportable slot-machine winnings and $300 withholding; report gross winnings and claim withholding separately.","A W-2G is an information return, not proof that only the reported winnings are taxable.","gambling;winnings;withholding;W-2G","https://www.irs.gov/forms-pubs/about-form-w-2g",["Information return","Income"]),
form("W-3","Transmittal of Wage and Tax Statements","W-series","Employer W-2 summary","Summarizes paper Forms W-2 being transmitted to the Social Security Administration.","Employers filing paper Forms W-2; electronic filing generally uses SSA processes rather than a paper W-3.","W-3 totals reconcile with the attached W-2 forms; it is not an employee's individual income tax form.","W-3 is a transmittal, not an additional wage statement for each employee. Reconcile totals before submission.","Generally due with W-2 filing deadline, commonly Jan. 31 or next business day. Electronic filing rules and thresholds apply.","An employer sends 25 W-2s and completes the W-3 totals for wages and withholding reported on the forms.","W-3 goes to SSA; it is not filed by an employee with Form 1040.","employer;transmittal;W-2;SSA;W-3","https://www.irs.gov/forms-pubs/about-form-w-3",["Employer","Information return"]),
form("W-4","Employee's Withholding Certificate","W-series","Set wage withholding","Tells an employer how much federal income tax to withhold from an employee's wages based on filing status, multiple jobs, dependents, other income, deductions and extra withholding.","Employee completes and gives to employer; employer uses it for payroll withholding.","W-4 affects payroll withholding shown on W-2 Box 2; it does not directly report income or claim a tax deduction on Form 1040.","A W-4 is a withholding instruction, not a binding final tax election. Employees should update it when circumstances change.","No fixed income threshold. Exemption from withholding is available only when both prior-year and current-year tax liability tests are satisfied; exemption must generally be renewed annually.","An employee with two jobs uses the multiple-jobs worksheet or estimator to reduce underwithholding risk.","Withholding is a prepayment. A larger refund can mean more tax was prepaid, not that the tax liability was lower.","withholding;payroll;employee;W-4","https://www.irs.gov/forms-pubs/about-form-w-4",["Payroll","Employee"]),
form("W-4P","Withholding Certificate for Periodic Pension or Annuity Payments","W-series","Pension withholding","Allows a recipient of periodic pension or annuity payments to elect federal income tax withholding.","Recipient provides to payer of periodic pension or annuity distributions.","Withholding is generally reported on Form 1099-R and credited on Form 1040.","Different rules apply to nonperiodic payments and eligible rollover distributions; W-4P is not used for every distribution type.","No universal threshold; withholding election and default rules depend on payment type and recipient status.","A retiree receiving monthly pension payments submits W-4P to request additional federal withholding.","Distinguish periodic pension withholding (W-4P) from eligible rollover distribution withholding rules.","pension;annuity;withholding;W-4P","https://www.irs.gov/forms-pubs/about-form-w-4p",["Retirement","Withholding"]),
form("W-4V","Voluntary Withholding Request","W-series","Voluntary withholding","Allows individuals to request voluntary federal income tax withholding from certain government payments.","Recipient submits to the agency paying eligible government benefits.","Withholding may appear on SSA-1099 or other benefit statement and is claimed as a payment on Form 1040.","Voluntary withholding is available only for specified payments; it does not change whether the underlying benefit is taxable.","Social Security recipients may generally elect 7%, 10%, 12% or 22% withholding. Confirm current agency options.","A Social Security recipient elects 10% withholding to reduce the chance of a balance due when benefits are taxable.","W-4V is voluntary benefit withholding; it is not an employee payroll W-4.","benefits;Social Security;voluntary withholding;W-4V","https://www.irs.gov/forms-pubs/about-form-w-4v",["Benefits","Withholding"]),
form("W-7","Application for IRS Individual Taxpayer Identification Number","W-series","Apply for ITIN","Requests an Individual Taxpayer Identification Number for a person who is not eligible for a Social Security number but has a federal tax purpose.","Individual needing an ITIN for federal tax administration, generally submitting identity and foreign-status documentation.","ITIN is used on federal tax forms and information returns where an identifying number is required; it does not authorize work or establish immigration status.","ITIN is for tax processing only. It does not replace an SSN for employment eligibility and does not confer immigration status or work authorization.","ITINs can expire under certain non-use or renewal rules. Check current W-7 instructions and exceptions for attached returns.","A nonresident spouse without SSN eligibility applies for an ITIN to be included on a permitted joint return, if otherwise eligible.","An ITIN is not an SSN. Know the distinction between identity/tax processing and employment authorization.","ITIN;foreign individual;W-7;SSN","https://www.irs.gov/forms-pubs/about-form-w-7",["International","Identity"]),
form("W-8BEN","Certificate of Foreign Status of Beneficial Owner for United States Tax Withholding and Reporting (Individuals)","W-series","Foreign individual treaty claim","Documents that an individual beneficial owner is foreign and, where applicable, claims a reduced withholding rate or exemption under an income tax treaty.","Foreign individual beneficial owner gives form to withholding agent or payer; generally not filed directly with IRS.","Payer uses the certificate to apply correct Chapter 3 withholding/reporting; related payments may be reported on Forms 1042-S or 1099 depending on status and payment.","W-8BEN is for individuals. It is generally valid through the end of the third calendar year following signature unless a change in circumstances or other rule shortens validity.","No dollar threshold; validity and treaty eligibility depend on facts, documentation and applicable treaty article.","A foreign individual receives U.S.-source royalty income and submits W-8BEN to claim a treaty rate if eligible.","Do not use W-8BEN-E for an individual or W-9 for a foreign person claiming foreign status.","foreign individual;treaty;withholding;W-8BEN","https://www.irs.gov/forms-pubs/about-form-w-8-ben",["International","Withholding"]),
form("W-8BEN-E","Certificate of Status of Beneficial Owner for United States Tax Withholding and Reporting (Entities)","W-series","Foreign entity treaty claim","Documents foreign entity status, chapter 3/4 status and potential treaty benefits or withholding exemptions.","Foreign entity beneficial owner gives form to withholding agent or payer.","Payer uses it for withholding and reporting decisions; payments may be reported on Forms 1042-S and related filings.","This form is for entities, not individuals. FATCA classification and documentation sections must be completed accurately.","No dollar threshold; entity classification, ownership, treaty eligibility and FATCA status determine treatment.","A foreign corporation receiving U.S.-source interest provides W-8BEN-E with the appropriate chapter 4 status and treaty claim if eligible.","W-8BEN-E is lengthy because entity status and FATCA classification matter; do not treat it as a simple W-9 substitute.","foreign entity;FATCA;treaty;W-8BEN-E","https://www.irs.gov/forms-pubs/about-form-w-8-ben-e",["International","Withholding"]),
form("W-9","Request for Taxpayer Identification Number and Certification","W-series","U.S. payee identification","Provides a U.S. person’s correct taxpayer identification number and certifications to a requester for information reporting and backup withholding purposes.","U.S. person gives completed W-9 to payer, client, bank or other requester; generally not filed directly with IRS by the payee.","Requester uses information to prepare forms such as 1099-NEC, 1099-MISC, 1099-INT or 1099-K and to determine backup withholding.","W-9 is generally for U.S. persons. A foreign person generally provides an appropriate W-8 form instead. Incorrect or missing TIN certification can trigger backup withholding.","Backup withholding rate is generally 24% when required. Information-return reporting thresholds depend on payment type and current law.","A business hires a U.S. freelance designer and requests Form W-9 to obtain name, address, tax classification and TIN before issuing a potential 1099-NEC.","W-9 is a request/certification form; it is not itself an income tax return or a 1099.","TIN;backup withholding;vendor;W-9;1099","https://www.irs.gov/forms-pubs/about-form-w-9",["Information reporting","Payee"])
];

export const FLASHCARDS_PART1 = [
{id:"fc01",category:"1040",front:"What is Form 1040's main role?",back:"It summarizes individual income, deductions, credits, payments and refund or balance due."},
{id:"fc02",category:"1040",front:"Does an extension extend the time to pay?",back:"No. It generally extends filing time, not the payment due date."},
{id:"fc03",category:"Filing status",front:"What is the 2026 standard deduction for Single?",back:"$16,100, before any additional age/blindness amount."},
{id:"fc04",category:"Filing status",front:"What is the 2026 standard deduction for HOH?",back:"$24,150, before any additional age/blindness amount."},
{id:"fc05",category:"Schedules",front:"Which schedule reports sole proprietor profit?",back:"Schedule C; net profit generally flows to Schedule 1 and Schedule SE."},
{id:"fc06",category:"Schedules",front:"Which schedule reports capital gains and losses?",back:"Schedule D, often supported by Form 8949."},
{id:"fc07",category:"Schedules",front:"What does Schedule SE calculate?",back:"Social Security and Medicare taxes on net earnings from self-employment."},
{id:"fc08",category:"W-series",front:"Which W form reports employee annual wages?",back:"Form W-2; Box 1 wages and Box 2 federal withholding are commonly used on Form 1040."},
{id:"fc09",category:"W-series",front:"Who generally provides Form W-9?",back:"A U.S. person provides it to a requester/payer for TIN and certification."},
{id:"fc10",category:"W-series",front:"W-8BEN vs. W-8BEN-E?",back:"W-8BEN is for foreign individuals; W-8BEN-E is for foreign entities."},
{id:"fc11",category:"W-series",front:"Does Form W-4 report income to the IRS?",back:"No. It tells an employer how to calculate federal income tax withholding."},
{id:"fc12",category:"Income",front:"What is the general capital-gain long-term holding period?",back:"More than one year; one year or less is generally short-term."},
{id:"fc13",category:"Dependency",front:"What is the general qualifying-child age test?",back:"Under 19, or under 24 if a full-time student; any age if permanently and totally disabled."},
{id:"fc14",category:"Dependency",front:"What support test applies to a qualifying relative?",back:"The taxpayer generally provides more than half of the person's total support."},
{id:"fc15",category:"Estimated tax",front:"What is a common estimated-tax safe harbor?",back:"Generally 90% of current-year tax or 100% of prior-year tax; 110% may apply to higher-income taxpayers."},
{id:"fc16",category:"Business",front:"What are the IRS worker-classification categories?",back:"Behavioral control, financial control and type of relationship."},
{id:"fc17",category:"Business",front:"Does receiving Form 1099-K make the full amount taxable income?",back:"No. Reconcile gross payment transactions to actual taxable receipts, refunds, fees and non-income transfers."},
{id:"fc18",category:"Ethics",front:"What does Circular 230 govern?",back:"Practice before the IRS by attorneys, CPAs, EAs and other covered practitioners."},
{id:"fc19",category:"Limitations",front:"What is the general federal assessment limitation period?",back:"Generally 3 years, with important 6-year and unlimited-period exceptions."},
{id:"fc20",category:"Penalties",front:"What is the general failure-to-file penalty rate?",back:"Generally 5% of unpaid tax per month or part, up to 25%, subject to special rules."}
];


// -----------------------------------------------------------------------------
// PART 2 — Forms 1099 and 1098 information-return families.
// Reporting thresholds below describe payer filing obligations, not whether
// the recipient must report taxable income. Income can be taxable even when
// no information return is required or received.
// -----------------------------------------------------------------------------
export const FORMS_PART2 = [
form("1099-NEC","Nonemployee Compensation","1099 series","Business service payments","Reports qualifying payments made in the course of a trade or business to nonemployees for services, including fees paid to independent contractors, certain professional service providers and attorneys. It replaced the former use of Form 1099-MISC box 7 for nonemployee compensation.","A business or other payer generally furnishes it to a service provider and files it with the IRS when the reporting rules apply. The recipient uses it to reconcile business receipts; the payer retains records and the payee's W-9.","Sole proprietor income generally goes to Schedule C (or the appropriate business return). Net profit generally flows through Schedule 1 to Form 1040; self-employment tax is generally computed on Schedule SE. Entity recipients report under their entity tax regime.","For payments made in 2026, the general statutory reporting threshold for covered business payments increased from $600 to $2,000. Certain exceptions and special categories remain; backup withholding can require reporting regardless of amount. The threshold is a payer information-reporting rule, not a tax-free allowance.","Generally $2,000 or more in covered payments during 2026. A separate $5,000 threshold applies to certain direct sales of consumer products for resale. Payments to attorneys have specific rules; backup withholding can trigger filing at any amount.","A company pays a freelance designer $3,400 for business services. It generally issues Form 1099-NEC for 2026. The designer reports gross business receipts, deducts substantiated ordinary and necessary expenses, and calculates net profit; the form amount is not automatically net profit.","Classification comes first. A worker who is actually an employee should generally receive Form W-2, not Form 1099-NEC. A 1099 does not decide worker status.","independent contractor;nonemployee compensation;Schedule C;W-9;2026 2000 threshold","https://www.irs.gov/forms-pubs/about-form-1099-nec",["Information reporting","Business"]),
form("1099-MISC","Miscellaneous Information","1099 series","Rents, prizes, royalties and other payments","Reports specified miscellaneous payments not reported on Form 1099-NEC, including rents, royalties, prizes and awards, certain medical/health-care payments, crop insurance proceeds and other enumerated categories.","Businesses, payers, property managers, insurers and other reporting persons furnish it to recipients and file with the IRS when the applicable category threshold and rules are met.","Recipient reports each item according to its character: rents/royalties or business income may go to Schedule E or C; prizes and awards generally go to Schedule 1; other items follow their specific tax treatment. The form itself does not determine deductibility or tax character.","For many covered payment categories made in 2026, the threshold increased to $2,000. Royalties generally retain a $10 threshold; other categories have distinct thresholds or all-amount rules. Gross proceeds paid to attorneys and other special payments have separate rules.","Common 2026 thresholds: generally $2,000 for rents, prizes/awards and many covered categories; $10 for royalties; certain payments are reportable at all amounts. Consult the 2026 General Instructions for the exact box and payee category.","A landlord receives $8,400 of rent reported on Form 1099-MISC. The recipient generally reports rental income on Schedule E, then considers allowable rental expenses and passive-activity limitations.","Distinguish 1099-MISC rents/royalties/prizes from 1099-NEC service compensation. A payment can be reportable even if the recipient is a corporation for categories with no corporate exception.","rent;royalty;prize;Schedule E;1099-MISC","https://www.irs.gov/forms-pubs/about-form-1099-misc",["Information reporting","Business"]),
form("1099-K","Payment Card and Third Party Network Transactions","1099 series","Payment platform gross payments","Reports gross payment transactions processed through payment cards or third-party settlement networks, such as payment apps and online marketplaces. The reported gross amount is not necessarily profit, taxable income or cash actually retained.","Payment settlement entities, merchant acquiring entities and third-party settlement organizations furnish it to participating payees and file with the IRS under the applicable rules.","Business receipts generally flow to Schedule C or the appropriate entity return. Personal-item sales are analyzed transaction by transaction: gain may be capital gain; a loss on personal-use property is generally nondeductible. Reconcile gross amounts to refunds, fees, sales tax, duplicate transfers and cost basis.","For third-party settlement organizations (TPSOs), the restored federal de minimis reporting rule generally requires both more than $20,000 in gross reportable payments and more than 200 transactions in the calendar year. Payment-card transactions have no comparable de minimis threshold. A platform may voluntarily issue a form below the TPSO threshold.","TPSO test: gross payments exceed $20,000 AND transaction count exceeds 200. Payment-card settlement reporting can apply at any amount. This is an information-return threshold only; taxable income must be reported even without Form 1099-K.","A seller receives a $12,000 Form 1099-K total, including $2,000 of refunded sales and $500 of platform fees. The taxpayer reconciles the gross total to actual transactions and tax character rather than automatically reporting $12,000 as net profit.","Never equate Form 1099-K gross payments with taxable income. Maintain transaction-level records and distinguish business sales from gifts, reimbursements and personal-property sales.","payment app;third party network;gross payments;marketplace;1099-K","https://www.irs.gov/forms-pubs/about-form-1099-k",["Information reporting","Payments"]),
form("1099-INT","Interest Income","1099 series","Bank and investment interest","Reports taxable and tax-exempt interest and certain related amounts paid during the year, commonly by banks, credit unions, brokers, government entities and other payers.","Financial institution or other payer furnishes it to the beneficial owner and files it with the IRS when required.","Taxable interest is generally reported on Schedule B when required and then Form 1040 interest income. Tax-exempt interest is also disclosed on Form 1040 but is generally excluded from taxable income; it may affect other calculations.","Payer generally reports at least $10 of reportable interest in specified boxes, with a $600 threshold for certain interest paid in the course of a trade or business. Backup withholding and foreign-tax situations can require reporting regardless of amount.","Generally $10 for specified interest boxes; certain business-interest payments use $600. No minimum amount makes otherwise taxable interest tax-free.","A taxpayer receives $380 of savings-account interest and $45 of Treasury interest. The taxpayer reports taxable interest; Treasury interest is generally federally taxable but exempt from state and local income taxes.","Interest may be taxable even when no Form 1099-INT arrives. Tax-exempt municipal interest is disclosed but generally not included in federal taxable interest.","interest;bank;Treasury;Schedule B;1099-INT","https://www.irs.gov/forms-pubs/about-form-1099-int",["Investment income","Individuals"]),
form("1099-DIV","Dividends and Distributions","1099 series","Stock and fund distributions","Reports dividends, capital-gain distributions, tax-exempt-interest dividends, foreign tax paid and certain other corporate or regulated investment company distributions.","Corporations, brokers, mutual funds and other payers furnish it to shareholders/beneficial owners and file it with the IRS.","Ordinary dividends generally flow to Form 1040; qualified dividends may receive preferential rates. Capital-gain distributions are generally reported on Schedule D, subject to the applicable election/exception. Foreign tax may support a credit or deduction.","Generally reportable at $10 or more for dividends and distributions, or when foreign tax is withheld/paid or backup withholding applies regardless of amount. Liquidation distributions have a separate threshold.","Generally $10; $600 or more for certain liquidation distributions. Reporting thresholds do not determine whether a distribution is taxable.","A mutual fund reports $900 ordinary dividends, $300 qualified dividends included within that amount, and $250 capital-gain distributions. The taxpayer does not add qualified dividends a second time; the qualified portion is a subset of ordinary dividends.","Qualified dividends are not a separate additional payment. They are part of ordinary dividends and may qualify for preferential tax rates if holding-period and other tests are met.","ordinary dividends;qualified dividends;capital gain distributions;foreign tax credit","https://www.irs.gov/forms-pubs/about-form-1099-div",["Investment income","Individuals"]),
form("1099-B","Proceeds From Broker and Barter Exchange Transactions","1099 series","Brokerage sales","Reports proceeds from sales or exchanges of securities, commodities, certain digital assets where applicable, and barter transactions. It may include basis, acquisition date, holding period and withholding information.","Broker, barter exchange or other reporting entity furnishes it to the customer and files it with the IRS.","Sales are generally reconciled on Form 8949 and summarized on Schedule D. Some transactions with basis reported to IRS may be eligible for direct Schedule D reporting when the instructions permit. Digital asset reporting may involve Form 1099-DA under current rules.","There is generally no broad dollar minimum that makes a reportable broker sale exempt from the taxpayer's reporting obligation. Covered broker reporting and basis-reporting rules vary by asset and transaction date.","Reportable sales can be required even for small proceeds or a loss. The taxpayer's gain/loss is proceeds less adjusted basis and selling costs, not the proceeds figure alone.","A broker reports $7,500 proceeds and $5,900 basis. Ignoring adjustments and fees, the realized gain is $1,600; holding period determines short- or long-term treatment.","Proceeds are not gain. Reconcile every sale to basis, wash-sale adjustments, corporate actions and holding period.","broker;stock sale;basis;capital gain;Form 8949;Schedule D","https://www.irs.gov/forms-pubs/about-form-1099-b",["Investment income","Individuals"]),
form("1099-R","Distributions From Pensions, Annuities, Retirement or Profit-Sharing Plans, IRAs, Insurance Contracts, etc.","1099 series","Retirement distributions","Reports distributions from retirement plans, IRAs, pensions, annuities, insurance contracts and certain other arrangements, including gross distribution, taxable amount, withholding and distribution codes.","Plan administrator, IRA trustee, insurer or other payer furnishes it to the recipient and files it with the IRS.","Taxable IRA distributions generally flow to Form 1040 IRA distribution lines; pensions/annuities flow to pension lines. Rollovers, basis recovery, qualified charitable distributions and exceptions may require Form 8606 or other supporting analysis.","Generally reportable for distributions of $10 or more, with special all-amount and withholding rules. Receipt of a 1099-R does not mean the entire gross amount is taxable.","$10 general reporting threshold; some transactions are reportable regardless. Taxability depends on account type, basis, rollover status, age, exceptions and distribution code.","A taxpayer receives a $20,000 traditional IRA distribution, with $4,000 of nondeductible basis tracked on Form 8606. The taxable portion is determined using the pro-rata rules, not simply assumed to be $20,000.","Read Box 7 distribution code and Box 2a taxable amount, but verify them against the taxpayer's facts. A direct rollover and a taxable cash distribution are not equivalent.","IRA;401k;pension;annuity;rollover;Form 8606","https://www.irs.gov/forms-pubs/about-form-1099-r",["Retirement","Individuals"]),
form("1099-G","Certain Government Payments","1099 series","Unemployment and state tax refunds","Reports specified government payments, commonly unemployment compensation, certain agricultural payments, taxable grants and state/local income tax refunds or credits.","Federal, state or local government agency furnishes it to the recipient and files it with the IRS when required.","Unemployment compensation is generally reported as other income on Form 1040. A state income tax refund is taxable only to the extent the tax benefit rule applies, often requiring review of the prior-year deduction choice and tax benefit.","There is no single universal threshold for all boxes. Unemployment compensation reporting and state tax refund reporting have distinct rules; some amounts are reportable regardless of threshold.","Use the box-specific instructions. Unemployment compensation is generally reportable in full; a state tax refund is not automatically taxable merely because Form 1099-G was issued.","A taxpayer receives $5,000 unemployment compensation and a $700 state refund. The unemployment amount is generally taxable federally; the state refund is tested under the tax benefit rule based on the prior-year return.","Do not automatically include every state refund as taxable income. Determine whether the taxpayer itemized and received a tax benefit from the state-tax deduction.","unemployment;state refund;tax benefit rule;government payment","https://www.irs.gov/forms-pubs/about-form-1099-g",["Government payments","Individuals"]),
form("1099-C","Cancellation of Debt","1099 series","Discharged debt","Reports a creditor's cancellation of $600 or more of debt, including certain recourse and nonrecourse debt events. Cancellation of debt (COD) can create gross income unless an exclusion or exception applies.","Applicable financial institution, governmental unit, credit union or other covered creditor furnishes it to the debtor and files it with the IRS.","Taxable COD is generally reported as other income or business income depending on context. Form 982 is used to claim certain exclusions and attribute tax-attribute reductions where required.","A creditor generally reports cancellation of $600 or more. The $600 information-reporting threshold does not create a $600 tax-free exclusion; smaller COD can still be taxable.","Generally $600 or more for creditor reporting. Insolvency, bankruptcy, qualified farm debt, qualified real property business debt and other exclusions have their own conditions and limitations.","A lender cancels $18,000 of credit-card debt. The taxpayer determines insolvency immediately before discharge; if liabilities exceed fair market value of assets by $7,000, the insolvency exclusion may shelter up to $7,000, subject to the detailed rules.","Form 1099-C is evidence of a discharge, not proof that the entire amount is taxable. Test exclusions and exceptions carefully and document asset/liability values.","cancellation of debt;COD;insolvency;bankruptcy;Form 982","https://www.irs.gov/forms-pubs/about-form-1099-c",["Debt","Individuals"]),
form("1099-S","Proceeds From Real Estate Transactions","1099 series","Real estate sale proceeds","Reports gross proceeds from covered real estate transactions, including sales or exchanges of real property and certain other transfers.","Closing agent, real estate reporting person, attorney or other designated person furnishes it to transferor and files it with the IRS.","Sale is generally reported on Form 8949 and Schedule D for capital assets, or Form 4797 for business/investment property where applicable. Principal-residence exclusion under Section 121 may apply if ownership/use tests are satisfied.","Generally reportable when gross proceeds are $600 or more, subject to exceptions and certification rules. The form reports gross proceeds, not taxable gain.","$600 general reporting threshold; exclusion eligibility and gain computation depend on ownership, use, basis, improvements, selling costs and prior exclusion use.","A homeowner sells a principal residence for $520,000 with adjusted basis of $310,000 and eligible selling costs of $30,000. Realized gain is $180,000 before applying any Section 121 exclusion.","A 1099-S does not calculate gain. Reconstruct basis, capital improvements and selling costs; verify the principal-residence exclusion requirements.","real estate;closing;home sale;Section 121;Schedule D;Form 4797","https://www.irs.gov/forms-pubs/about-form-1099-s",["Property transactions","Individuals"]),
form("1099-SA","Distributions From an HSA, Archer MSA, or Medicare Advantage MSA","1099 series","Medical savings account distributions","Reports distributions from health savings accounts, Archer medical savings accounts and Medicare Advantage MSAs.","HSA/MSA trustee or custodian furnishes it to the account holder and files it with the IRS.","Recipient generally uses Form 8889 for HSA distributions; taxable nonqualified distributions flow to Form 1040 with any additional tax. Archer MSA distributions use Form 8853.","Generally report distributions regardless of amount. Qualified medical expenses, rollover, mistaken-distribution correction and death/disability rules determine tax treatment.","No general minimum dollar reporting threshold for distributions. HSA additional tax on nonqualified distributions is generally 20%, with statutory exceptions such as after age 65, disability or death.","An HSA owner receives $2,400 and spends $1,900 on qualified medical expenses. The remaining $500 may be taxable and subject to additional tax unless an exception applies; Form 8889 reconciles distributions.","A distribution is not automatically tax-free because it came from an HSA. Match distributions to qualified medical expenses and retain receipts.","HSA;medical savings;Form 8889;qualified medical expenses","https://www.irs.gov/forms-pubs/about-form-1099-sa",["Health accounts","Individuals"]),
form("1099-Q","Payments From Qualified Education Programs","1099 series","529 and Coverdell distributions","Reports distributions from qualified tuition programs (529 plans) and Coverdell education savings accounts.","Program administrator or trustee furnishes it to the beneficiary, account owner or other recipient as applicable and files it with the IRS.","Recipient coordinates the distribution with qualified education expenses. Taxable earnings may be reported as other income; tax-free treatment and education-credit coordination require expense allocation and records.","Generally reports distributions; there is no broad minimum threshold that makes a small distribution automatically tax-free. Earnings are taxable to the extent distributions exceed adjusted qualified education expenses, subject to applicable rules.","No general tax-free dollar threshold. Qualified expenses, scholarships, tax-free educational assistance, room-and-board eligibility and credit coordination determine treatment.","A 529 plan distributes $12,000. The family has $10,000 of adjusted qualified expenses after scholarship adjustments; the earnings portion allocable to the excess distribution may be taxable.","Do not use the same tuition expense to justify both tax-free 529 treatment and an education credit. Coordinate expenses and beneficiary-level rules.","529 plan;Coverdell;education savings;qualified expenses","https://www.irs.gov/forms-pubs/about-form-1099-q",["Education","Individuals"]),
form("1098","Mortgage Interest Statement","1098 series","Mortgage interest paid","Reports mortgage interest and certain related amounts received by a lender or other recipient in the course of a trade or business, secured by real property.","Mortgage lender, servicer or other covered recipient furnishes it to the borrower and files it with the IRS when reporting rules apply.","Borrower may use it to substantiate a potential itemized deduction on Schedule A, subject to qualified residence, debt-limit, tracing and other Section 163(h) rules. Points and mortgage insurance treatment require separate analysis.","Generally required when a covered recipient receives $600 or more of mortgage interest on a mortgage during the calendar year. Receipt does not establish that all interest is deductible.","$600 reporting threshold for covered mortgage interest. Deductibility depends on itemizing, qualified residence status, acquisition indebtedness limits and applicable law.","A taxpayer pays $9,600 mortgage interest on a qualifying home. The amount may be included on Schedule A only if the taxpayer itemizes and the debt and residence satisfy the deduction rules.","The amount shown on Form 1098 is not automatically deductible. Verify loan origination date, debt balance, use of proceeds and whether the home qualifies.","mortgage interest;Schedule A;home mortgage debt;1098","https://www.irs.gov/forms-pubs/about-form-1098",["Deductions","Individuals"]),
form("1098-E","Student Loan Interest Statement","1098 series","Student loan interest paid","Reports student loan interest received by a lender or loan servicer from a borrower during the year.","Eligible lender, financial institution, governmental unit or servicer receiving $600 or more in the course of business generally furnishes it to the borrower and files it with the IRS.","Eligible student loan interest may be claimed as an adjustment to income on Schedule 1, subject to filing-status, modified AGI, loan-purpose and dependency restrictions.","The lender reporting threshold is generally $600 per borrower for interest received in the course of business. The borrower's deduction has a separate statutory maximum and income phase-out.","2026 reporting threshold: $600. Deduction maximum is generally $2,500, subject to 2026 MAGI phase-out ranges and disqualifying filing status; verify the 2026 Form 1040 instructions for final ranges.","A borrower pays $1,100 of qualifying student-loan interest. The taxpayer may deduct up to the eligible amount, capped at $2,500 and reduced or eliminated by the applicable MAGI phase-out.","The $600 form-issuance threshold is not the deduction limit. A borrower may be entitled to deduct qualifying interest even if no 1098-E is issued.","student loan interest;Schedule 1;education;1098-E","https://www.irs.gov/forms-pubs/about-form-1098-e",["Education","Adjustments"]),
form("1098-T","Tuition Statement","1098 series","Qualified tuition reporting","Reports qualified tuition and related expenses billed or received by an eligible educational institution, scholarships/grants and other education-related information.","Eligible educational institution furnishes it to the student and files it with the IRS. The student or taxpayer uses it with account statements and expense records.","Supports analysis for the American Opportunity Tax Credit and Lifetime Learning Credit, generally claimed on Form 8863 and carried to Form 1040. The 1098-T alone does not establish credit eligibility or qualified expenses.","Institutions generally report when reportable payments for qualified tuition and related expenses are received or billed under the applicable rules; exceptions and reporting methods apply. There is not a universal $600 tuition-reporting floor.","No simple $600 threshold. Credit limits and MAGI phase-outs apply separately: AOTC maximum $2,500 per eligible student; LLC maximum $2,000 per return, subject to statutory requirements and current-year phase-outs.","A student has $7,000 of qualified tuition and $1,000 of tax-free scholarship. The family must allocate expenses correctly and check who may claim the student and whether AOTC or LLC requirements are met.","A 1098-T is an information statement, not a credit award. Confirm enrollment, degree status, years claimed, felony drug-conviction rule for AOTC, dependency and expense allocation.","tuition;AOTC;LLC;Form 8863;education credit","https://www.irs.gov/forms-pubs/about-form-1098-t",["Education","Credits"]),
form("1098-C","Contributions of Motor Vehicles, Boats, and Airplanes","1098 series","Qualified vehicle donation","Acknowledges a charitable contribution of a qualified motor vehicle, boat or airplane when the applicable substantiation rules require the donee organization to file and furnish the form.","Qualified charitable organization generally files and furnishes it to the donor for a donated vehicle, boat or airplane subject to the statutory reporting rules.","Donor uses it to substantiate a potential charitable contribution deduction on Schedule A if itemizing. Deduction amount is generally tied to gross proceeds from the charity's sale, unless a statutory exception permits fair market value.","For a vehicle donation with claimed value over $500, special written acknowledgment and Form 1098-C substantiation rules generally apply. Timing and contemporaneous acknowledgment rules are strict.","Generally applies when claimed deduction exceeds $500. The deductible amount may be gross sale proceeds rather than donor-estimated fair market value, subject to exceptions.","A donor gives a car to a qualified charity. The charity sells it for $3,200 and furnishes Form 1098-C; the donor generally uses the reported gross proceeds, subject to the substantiation and deduction rules.","Do not assume a donated car is deductible at private-party fair market value. Review the charity's use/sale certification and contemporaneous acknowledgment deadline.","vehicle donation;charitable contribution;Schedule A;1098-C","https://www.irs.gov/forms-pubs/about-form-1098-c",["Charitable contributions","Individuals"])
];

export const FLASHCARDS_PART2 = [
{id:"fc21",category:"1099 forms",front:"What is the general 2026 Form 1099-NEC threshold?",back:"$2,000 for covered business service payments, subject to exceptions and backup-withholding rules. This is a payer reporting threshold, not a tax-free allowance."},
{id:"fc22",category:"1099 forms",front:"What are the two parts of the 1099-K TPSO de minimis test?",back:"Gross reportable payments exceed $20,000 AND the number of transactions exceeds 200. Payment-card reporting has no comparable de minimis threshold."},
{id:"fc23",category:"1099 forms",front:"Does a 1099-K amount equal taxable profit?",back:"No. It is gross transaction reporting. Reconcile refunds, fees, basis, sales tax, transfers and transaction character."},
{id:"fc24",category:"1099 forms",front:"Where does 1099-INT taxable interest generally flow?",back:"Form 1040 interest income; Schedule B is used when required."},
{id:"fc25",category:"1099 forms",front:"Are qualified dividends added on top of ordinary dividends?",back:"No. Qualified dividends are included within ordinary dividends and may receive preferential rates."},
{id:"fc26",category:"1099 forms",front:"What is the key calculation for a 1099-B sale?",back:"Gain or loss generally equals proceeds minus adjusted basis and applicable adjustments—not proceeds alone."},
{id:"fc27",category:"1099 forms",front:"Does every 1099-R distribution have to be fully taxable?",back:"No. Rollovers, after-tax basis, qualified distributions and other exceptions can make some or all of a distribution nontaxable."},
{id:"fc28",category:"1099 forms",front:"Is every state tax refund on Form 1099-G taxable?",back:"No. Apply the tax benefit rule, considering whether the taxpayer itemized and received a federal tax benefit in the prior year."},
{id:"fc29",category:"1099 forms",front:"What does Form 1099-C report?",back:"A creditor's cancellation of debt. Test bankruptcy, insolvency and other exclusions; the reported amount is not automatically taxable in full."},
{id:"fc30",category:"1099 forms",front:"Does Form 1099-S report the taxable gain on a home sale?",back:"No. It generally reports gross proceeds. Calculate gain using basis and selling costs, then test Section 121."},
{id:"fc31",category:"1099 forms",front:"Which form reports HSA distributions?",back:"Form 1099-SA. Reconcile distributions and qualified medical expenses on Form 8889."},
{id:"fc32",category:"1099 forms",front:"Can the same tuition expense support tax-free 529 treatment and an education credit?",back:"No. Coordinate expenses; the same expense cannot be used twice for overlapping tax benefits."},
{id:"fc33",category:"1098 forms",front:"Is the mortgage interest shown on Form 1098 automatically deductible?",back:"No. Itemizing, qualified-residence status, acquisition-debt limits and other requirements must be met."},
{id:"fc34",category:"1098 forms",front:"What is the 1098-E reporting threshold?",back:"Generally $600 of student-loan interest received from a borrower in the course of business. The deduction has separate limits and phase-outs."},
{id:"fc35",category:"1098 forms",front:"Does Form 1098-T guarantee an education credit?",back:"No. Confirm student eligibility, qualified expenses, scholarships, dependency and income phase-outs."},
{id:"fc36",category:"1098 forms",front:"What is the key 1098-C vehicle-donation rule?",back:"For a claimed deduction over $500, special substantiation generally applies; the deduction is often based on the charity's gross sale proceeds."}
];

