// Part 7 — original EA-style practice bank. Questions are original study items, not actual SEE questions.
export const QUESTIONS_PART7 = [
// Part 1 — Individuals
{id:"p1q1",part:1,topic:"Filing status",question:"A taxpayer is unmarried on December 31, paid more than half the cost of keeping up a home, and has a qualifying child who lived in the home for more than half the year. Which filing status may be available?",choices:["Single only","Head of household","Married filing separately","Qualifying surviving spouse"],answer:1,explanation:"Head of household may apply when the taxpayer meets the unmarried/considered-unmarried, household-cost and qualifying-person tests. The facts must satisfy all requirements; merely having a dependent is not enough."},
{id:"p1q2",part:1,topic:"Dependency",question:"Which statement is generally part of the qualifying-child support test?",choices:["The taxpayer must provide more than half of the child's support","The child must not have provided more than half of their own support","The child's gross income must be below the annual exemption amount","The child must be under age 18 in every case"],answer:1,explanation:"For the qualifying-child test, the child generally must not have provided more than half of their own support. The more-than-half support test for support provided by the taxpayer belongs to the qualifying-relative test."},
{id:"p1q3",part:1,topic:"Gross income",question:"A cash-method taxpayer receives a check on December 29 but does not deposit it until January 4. If the check is not subject to a substantial restriction, when is it generally included in income?",choices:["December, when received","January, when deposited","Only when it clears the bank","The taxpayer may choose either year"],answer:0,explanation:"Under the constructive-receipt doctrine, income is generally taxable when actually or constructively received. Delaying deposit of an unrestricted check normally does not defer income."},
{id:"p1q4",part:1,topic:"Capital gains",question:"An individual sells an investment asset 14 months after acquiring it. Assuming the asset is a capital asset and no special rule applies, how is the gain generally characterized?",choices:["Short-term capital gain","Long-term capital gain","Ordinary business income","Tax-exempt income"],answer:1,explanation:"A capital asset held for more than one year generally produces long-term capital gain or loss. The holding period is measured under the applicable acquisition and disposition rules."},
{id:"p1q5",part:1,topic:"Adjustments",question:"Where is the deductible portion of an individual's self-employment tax generally claimed?",choices:["As a Schedule C operating expense","As an adjustment to income on Schedule 1","As an itemized deduction on Schedule A","As a tax credit on Form 1040"],answer:1,explanation:"The deductible portion of self-employment tax is generally an adjustment to income, computed through Schedule SE and reported on Schedule 1. It is not a Schedule C business expense."},
{id:"p1q6",part:1,topic:"Education credits",question:"Which form is commonly used to calculate the American Opportunity Tax Credit and Lifetime Learning Credit?",choices:["Form 8863","Form 2441","Form 5695","Form 8889"],answer:0,explanation:"Form 8863 is used to calculate education credits. Eligibility, qualified expenses, student status, dependency and income limitations must also be considered."},
{id:"p1q7",part:1,topic:"Itemized deductions",question:"A taxpayer chooses to itemize deductions. Which schedule is generally used to report itemized deductions for an individual Form 1040?",choices:["Schedule C","Schedule A","Schedule E","Schedule SE"],answer:1,explanation:"Schedule A is used for itemized deductions such as qualifying medical expenses, taxes, interest, gifts to charity and certain other deductions, subject to limitations."},
{id:"p1q8",part:1,topic:"Retirement",question:"A taxpayer makes a direct trustee-to-trustee transfer from one traditional IRA to another traditional IRA. Which statement is generally correct?",choices:["It is generally not a taxable distribution if properly executed","It is always taxable as wages","It is always subject to the 10% additional tax","It is treated as a charitable contribution"],answer:0,explanation:"A properly executed trustee-to-trustee transfer between traditional IRAs is generally not treated as a distribution paid to the taxpayer and is not currently taxable. Rollovers and conversions have separate timing and reporting rules."},
{id:"p1q9",part:1,topic:"Foreign tax credit",question:"Which form is generally used by an individual to claim a credit for qualifying foreign income taxes?",choices:["Form 1116","Form 2555","Form 8938","Form 5471"],answer:0,explanation:"Form 1116 generally computes the foreign tax credit for individuals. Form 2555 is used for the foreign earned income and housing exclusions; the forms serve different purposes."},
{id:"p1q10",part:1,topic:"Estimated tax",question:"An individual taxpayer has income not subject to sufficient withholding. Which mechanism may be used to pay federal income tax during the year?",choices:["Quarterly estimated tax payments","A Form 941 filed by the individual","A Form 940 filed with the state","A Schedule K-1 payment"],answer:0,explanation:"Individuals may need estimated tax payments when withholding and refundable credits will not cover the required amount. The safe-harbor and annualized-income rules can affect whether an underpayment penalty applies."},
// Part 2 — Businesses
{id:"p2q1",part:2,topic:"Entity classification",question:"A domestic eligible entity with two members is generally classified as what for federal income tax purposes if it has not elected corporate treatment?",choices:["A C corporation","A partnership","A disregarded entity","An S corporation automatically"],answer:1,explanation:"A domestic eligible entity with two or more members is generally classified as a partnership by default unless it elects corporate classification. An entity cannot become an S corporation automatically; it must meet eligibility rules and make a valid election."},
{id:"p2q2",part:2,topic:"Partnership taxation",question:"How is a partnership's ordinary business income generally taxed at the federal income-tax level?",choices:["The partnership pays regular corporate income tax on all profit","It passes through to partners, who generally report their distributive shares","It is always tax-exempt","It is taxed only when cash is distributed"],answer:1,explanation:"A partnership generally is a pass-through entity for federal income tax. Partners report their distributive shares whether or not cash is distributed, subject to the applicable character and allocation rules."},
{id:"p2q3",part:2,topic:"S corporations",question:"Which is generally required for a corporation to elect S corporation status?",choices:["It may have unlimited shareholders of any type","It must satisfy eligibility requirements and obtain required shareholder consent","It must have at least 100 shareholders","It must be publicly traded"],answer:1,explanation:"S corporation eligibility includes limits on number and type of shareholders, one class of stock (with voting-right distinctions), domestic status and required shareholder consent. Form 2553 is used to make the election."},
{id:"p2q4",part:2,topic:"C corporations",question:"Which return does a domestic C corporation generally file to report its federal income tax?",choices:["Form 1120","Form 1065","Form 1120-S","Schedule C"],answer:0,explanation:"A domestic C corporation generally files Form 1120. Partnerships generally file Form 1065, and eligible S corporations generally file Form 1120-S."},
{id:"p2q5",part:2,topic:"Basis",question:"Why is a partner's outside basis important?",choices:["It determines the partnership's payroll tax rate","It helps determine taxability of distributions and deductibility of partnership losses","It replaces the partnership's inside basis in all assets","It determines the partner's filing status"],answer:1,explanation:"Outside basis is the partner's tax basis in the partnership interest. It is relevant to loss limitations, distributions, sale of the interest and other tax consequences. It is distinct from the partnership's inside basis in its assets."},
{id:"p2q6",part:2,topic:"Depreciation",question:"Which form is generally used to claim depreciation and amortization, including Section 179 deductions?",choices:["Form 4562","Form 4797","Form 941","Form 709"],answer:0,explanation:"Form 4562 reports depreciation and amortization, certain listed property information and Section 179 expense deductions. The placed-in-service date, business use and property eligibility matter."},
{id:"p2q7",part:2,topic:"Payroll",question:"Which return does an employer generally use to report federal income tax withheld and Social Security and Medicare taxes?",choices:["Form 941","Form 940","Form 1065","Form 944 only in every case"],answer:0,explanation:"Form 941 is the quarterly federal employment tax return for most employers. Form 940 reports annual FUTA tax. Certain small employers may be authorized to file Form 944 annually instead of Form 941."},
{id:"p2q8",part:2,topic:"FUTA",question:"Which tax is reported on Form 940?",choices:["Federal unemployment tax (FUTA)","Employee federal income tax withholding","Corporate income tax","Self-employment tax"],answer:0,explanation:"Form 940 is the annual Federal Unemployment (FUTA) Tax Return. FUTA is generally an employer tax and is distinct from federal income tax withholding and FICA taxes reported on Form 941."},
{id:"p2q9",part:2,topic:"Business expenses",question:"A sole proprietor pays a personal vacation expense from the business bank account. How is the payment generally treated for federal income-tax purposes?",choices:["Deductible ordinary business expense","Personal expense, not deductible as a business expense","Depreciable business property","A payroll tax payment"],answer:1,explanation:"Personal expenses are not deductible as ordinary and necessary business expenses merely because they are paid from a business account. Proper books should identify and remove personal transactions from deductible business costs."},
{id:"p2q10",part:2,topic:"Asset dispositions",question:"Which form is generally used to report gains and losses from the sale or exchange of business property and certain involuntary conversions?",choices:["Form 4797","Form 8863","Form 1040-ES","Form 2848"],answer:0,explanation:"Form 4797 reports sales of business property and certain other transactions. Characterization may involve ordinary gain/loss, Section 1231 treatment and depreciation recapture."},
// Part 3 — Representation, practices and procedures
{id:"p3q1",part:3,topic:"Representation authority",question:"Which form generally authorizes an eligible representative to represent a taxpayer before the IRS for specified tax matters?",choices:["Form 8821","Form 2848","Form 4506-T","Form 9465"],answer:1,explanation:"Form 2848 is a Power of Attorney and Declaration of Representative. Form 8821 generally authorizes access to tax information but does not grant authority to represent the taxpayer before the IRS."},
{id:"p3q2",part:3,topic:"Tax information authorization",question:"What is the primary purpose of Form 8821?",choices:["Authorize representation and negotiation with the IRS","Authorize a designee to inspect or receive confidential tax information","Request an installment agreement","Appeal a tax assessment"],answer:1,explanation:"Form 8821 is a Tax Information Authorization. It permits designated persons to inspect or receive specified confidential tax information, but does not authorize them to advocate, negotiate or otherwise represent the taxpayer."},
{id:"p3q3",part:3,topic:"Collections",question:"Which statement best distinguishes a federal tax lien from a levy?",choices:["A lien is a legal claim against property; a levy is the legal seizure of property","A lien seizes wages immediately; a levy only gives public notice","They are identical terms","A levy is always voluntary"],answer:0,explanation:"A federal tax lien is the government's legal claim against a taxpayer's property when statutory conditions are met. A levy is an actual legal seizure of property or rights to property to satisfy a tax debt."},
{id:"p3q4",part:3,topic:"Collection due process",question:"Which form is commonly used to request a Collection Due Process or equivalent hearing after a qualifying lien or levy notice?",choices:["Form 12153","Form 433-F","Form 656","Form 843"],answer:0,explanation:"Form 12153 is used to request a Collection Due Process or equivalent hearing. The deadline and appeal rights depend on the notice and governing rules; read the notice carefully."},
{id:"p3q5",part:3,topic:"Installment agreements",question:"Which form is commonly used by an individual to request a monthly installment agreement?",choices:["Form 9465","Form 2848","Form 8275","Form 709"],answer:0,explanation:"Form 9465 is the Installment Agreement Request. Eligibility, payment options, fees, filing compliance and current IRS online options should be reviewed."},
{id:"p3q6",part:3,topic:"Appeals",question:"What is the general purpose of the IRS Independent Office of Appeals?",choices:["To provide an administrative, impartial forum to resolve tax disputes without litigation when possible","To prepare the taxpayer's original return","To issue criminal convictions","To replace the Tax Court"],answer:0,explanation:"The IRS Independent Office of Appeals provides an administrative forum intended to resolve tax disputes impartially and avoid litigation when possible. Appeals is separate from the examination function."},
{id:"p3q7",part:3,topic:"Statute of limitations",question:"What is the general federal rule for the IRS period to assess additional tax when a return has been filed, absent an exception?",choices:["Three years from the return filing date or due date, as applicable under the statute","One year from payment","Ten years in every case","There is no limitation period for any return"],answer:0,explanation:"The general assessment limitation period is commonly three years, measured under the statutory rules. Exceptions include substantial omissions, fraud, failure to file and other circumstances. The exact starting date must be analyzed."},
{id:"p3q8",part:3,topic:"Taxpayer rights",question:"Which publication explains the Taxpayer Bill of Rights and fundamental taxpayer protections?",choices:["Publication 1","Publication 17 only","Publication 463","Publication 535"],answer:0,explanation:"IRS Publication 1, Your Rights as a Taxpayer, describes taxpayer rights during examinations, appeals, collections and other interactions with the IRS."},
{id:"p3q9",part:3,topic:"Circular 230",question:"Under Circular 230, what should a practitioner generally do when a client requests that known taxable income be omitted from a return?",choices:["Comply if the client signs a waiver","Refuse to prepare or submit a knowingly false return and explain the reporting obligation","Report only the amount supported by a Form 1099","Move the income to a different tax year without basis"],answer:1,explanation:"A client's instruction does not excuse a practitioner from professional standards. The practitioner must not knowingly assist a false return or evasion and should take appropriate steps consistent with law and professional duties."},
{id:"p3q10",part:3,topic:"Innocent spouse relief",question:"Which form is generally used to request innocent spouse relief from joint tax liability?",choices:["Form 8857","Form 8854","Form 911","Form 433-A"],answer:0,explanation:"Form 8857 is the Request for Innocent Spouse Relief. Relief depends on the statutory category and facts; filing the form does not automatically establish entitlement."}
];


